import java.io.BufferedReader;
import java.io.InputStreamReader;

class Solution {
    public char findKthBit(int n, int k) {
        int flip = 0;
        while (n > 1) {
            int mid = 1 << (n - 1);
            int length = (1 << n) - 1;
            if (k == mid) {
                return flip == 0 ? '1' : '0';
            }
            if (k > mid) {
                k = length - k + 1;
                flip ^= 1;
            }
            n--;
        }
        return flip == 0 ? '0' : '1';
    }
}

